/* ==========================================================================
   Formula eta funtzio trigonometrikoak · Batxilergoa 1 · Zientziak —
   diagnostic, guided practice, exercise bank and challenges, with the
   scope of unit 5 of Anaya Matemáticas I and the first half of unit 4 of
   Santillana 1.º Bachillerato Ciencias (all the exercises and numbers are
   our own). Every closed answer is a single number: an exact fraction, a
   decimal rounded as the prompt says, an angle in degrees between 0° and
   360° (none of the equations has 0° as a solution, so the ends never
   matter), how many solutions there are or their sum. Radians are asked
   as «aπ: find a». Identities come as «simplify and work it out at 30°».
   Inside formulas \sen, \tg, \cosec and \cotg are written in each
   language's names (text.ts). tests/trigonometria-batx1z-content.test.ts
   works every answer out again from its data.
   ========================================================================== */

/** A decimal written with the comma, as an exact fraction */
const v = (text: string): FractionValue => {
    const negative = text.startsWith('-')
    const [whole, decimals = ''] = text.replace('-', '').split(',')
    return fraction((negative ? -1 : 1) * Number(whole + decimals), 10 ** decimals.length)
}
const n = (value: number) => fraction(value)
const f = (numerator: number, denominator: number) => fraction(numerator, denominator)

const HUNDREDTHS = say('Hurbildu ehunenetara.', 'Aproxima a las centésimas.', 'قرّب إلى الأجزاء من مئة.', 'Round to two decimal places.')
const THOUSANDTHS = say('Hurbildu milarenetara.', 'Aproxima a las milésimas.', 'قرّب إلى الأجزاء من ألف.', 'Round to three decimal places.')
const AS_FRACTION = say('Eman zatiki gisa.', 'Dalo como fracción.', 'اكتبه كسرًا.', 'Give it as a fraction.')
/** A prompt followed by an instruction (rounding, fraction) */
const with_ = (prompt: LocalizedText, ...rules: LocalizedText[]): LocalizedText => ({
    eu: [prompt.eu, ...rules.map((rule) => rule.eu)].join(' '),
    es: [prompt.es, ...rules.map((rule) => rule.es)].join(' '),
    en: [prompt.en, ...rules.map((rule) => rule.en)].join(' '),
    ar: [prompt.ar, ...rules.map((rule) => rule.ar)].join(' ')
})

