export const trigonometryExerciseBank: ExerciseSection[] = [
    {
        id: 'ratios',
        title: say('Sei arrazoiak', 'Las seis razones', 'النسب الست', 'The six ratios'),
        items: [
            { id: 1, difficulty: 'easy', question: say('Pasatu 210° radianetara.', 'Pasa 210° a radianes.', 'حوّل 210° إلى الراديان.', 'Convert 210° to radians.'), solution: same('$210\\cdot\\frac{\\pi}{180}=\\frac{7\\pi}{6}$') },
            { id: 2, difficulty: 'easy', question: say('Zenbat gradu dira $\\frac{3\\pi}{5}$ rad?', '¿Cuántos grados son $\\frac{3\\pi}{5}$ rad?', 'كم درجة تساوي $\\frac{3\\pi}{5}$ rad؟', 'How many degrees is $\\frac{3\\pi}{5}$ rad?'), solution: same('$\\frac{3\\cdot 180°}{5}=108°$'), answer: { expected: n(108) } },
            { id: 3, difficulty: 'easy', question: say('$\\sen\\alpha=\\frac{1}{5}$ bada, zenbat da $\\cosec\\alpha$?', 'Si $\\sen\\alpha=\\frac{1}{5}$, ¿cuánto vale $\\cosec\\alpha$?', 'إذا كان $\\sen\\alpha=\\frac{1}{5}$، فكم قيمة $\\cosec\\alpha$؟', 'If $\\sin\\alpha=\\frac{1}{5}$, what is $\\csc\\alpha$?'), solution: same('$\\cosec\\alpha=\\frac{1}{\\sen\\alpha}=5$'), answer: { expected: n(5) } },
            { id: 4, difficulty: 'medium', question: with_(say('$\\cos\\alpha=-\\frac{8}{17}$ da, eta α bigarren koadrantean dago. Kalkulatu $\\cotg\\alpha$.', '$\\cos\\alpha=-\\frac{8}{17}$ y α está en el segundo cuadrante. Halla $\\cotg\\alpha$.', '$\\cos\\alpha=-\\frac{8}{17}$ وα في الربع الثاني. أوجد $\\cotg\\alpha$.', '$\\cos\\alpha=-\\frac{8}{17}$ and α is in the second quadrant. Find $\\cot\\alpha$.'), AS_FRACTION), solution: same('$\\begin{gathered}\\sen\\alpha=\\sqrt{1-\\frac{64}{289}}=\\frac{15}{17}\\\\ \\cotg\\alpha=-\\frac{8}{15}\\end{gathered}$'), answer: { expected: f(-8, 15) } },
            { id: 5, difficulty: 'medium', question: with_(say('$\\tg\\alpha=-\\frac{3}{4}$ da, eta α laugarren koadrantean dago. Kalkulatu $\\sec\\alpha$.', '$\\tg\\alpha=-\\frac{3}{4}$ y α está en el cuarto cuadrante. Halla $\\sec\\alpha$.', '$\\tg\\alpha=-\\frac{3}{4}$ وα في الربع الرابع. أوجد $\\sec\\alpha$.', '$\\tan\\alpha=-\\frac{3}{4}$ and α is in the fourth quadrant. Find $\\sec\\alpha$.'), AS_FRACTION), solution: same('$\\begin{gathered}\\sec^2\\alpha=1+\\frac{9}{16}=\\frac{25}{16}\\\\ \\sec\\alpha=\\frac{5}{4}\\end{gathered}$'), answer: { expected: f(5, 4) } },
            { id: 6, difficulty: 'medium', question: say('Sinplifikatu $\\cos\\alpha\\cdot\\tg\\alpha$, eta kalkulatu haren balioa $\\alpha=30°$ denean.', 'Simplifica $\\cos\\alpha\\cdot\\tg\\alpha$ y calcula su valor para $\\alpha=30°$.', 'بسّط $\\cos\\alpha\\cdot\\tg\\alpha$ واحسب قيمتها عندما $\\alpha=30°$.', 'Simplify $\\cos\\alpha\\cdot\\tan\\alpha$ and work out its value for $\\alpha=30°$.'), solution: same('$\\begin{gathered}\\cos\\alpha\\cdot\\frac{\\sen\\alpha}{\\cos\\alpha}=\\sen\\alpha\\\\ \\sen 30°=0{,}5\\end{gathered}$'), answer: { expected: v('0,5') } },
            { id: 7, difficulty: 'medium', question: say('Sinplifikatu $\\frac{\\sen^2\\alpha}{1-\\cos\\alpha}$, eta kalkulatu haren balioa $\\alpha=60°$ denean.', 'Simplifica $\\frac{\\sen^2\\alpha}{1-\\cos\\alpha}$ y calcula su valor para $\\alpha=60°$.', 'بسّط $\\frac{\\sen^2\\alpha}{1-\\cos\\alpha}$ واحسب قيمتها عندما $\\alpha=60°$.', 'Simplify $\\frac{\\sin^2\\alpha}{1-\\cos\\alpha}$ and work out its value for $\\alpha=60°$.'), solution: same('$\\begin{gathered}\\frac{(1-\\cos\\alpha)(1+\\cos\\alpha)}{1-\\cos\\alpha}=1+\\cos\\alpha\\\\ 1+\\cos 60°=1{,}5\\end{gathered}$'), answer: { expected: v('1,5') } },
            { id: 8, difficulty: 'hard', question: say('Sinplifikatu $\\sec^2\\alpha+\\cosec^2\\alpha-\\sec^2\\alpha\\cdot\\cosec^2\\alpha$.', 'Simplifica $\\sec^2\\alpha+\\cosec^2\\alpha-\\sec^2\\alpha\\cdot\\cosec^2\\alpha$.', 'بسّط $\\sec^2\\alpha+\\cosec^2\\alpha-\\sec^2\\alpha\\cdot\\cosec^2\\alpha$.', 'Simplify $\\sec^2\\alpha+\\csc^2\\alpha-\\sec^2\\alpha\\cdot\\csc^2\\alpha$.'), solution: say('$\\begin{gathered}\\sec^2\\alpha+\\cosec^2\\alpha\\\\ =\\frac{\\sen^2\\alpha+\\cos^2\\alpha}{\\sen^2\\alpha\\cos^2\\alpha}\\\\ =\\sec^2\\alpha\\cdot\\cosec^2\\alpha\\end{gathered}$ Kenketak 0 balio du.', '$\\begin{gathered}\\sec^2\\alpha+\\cosec^2\\alpha\\\\ =\\frac{\\sen^2\\alpha+\\cos^2\\alpha}{\\sen^2\\alpha\\cos^2\\alpha}\\\\ =\\sec^2\\alpha\\cdot\\cosec^2\\alpha\\end{gathered}$ La resta vale 0.', '$\\begin{gathered}\\sec^2\\alpha+\\cosec^2\\alpha\\\\ =\\frac{\\sen^2\\alpha+\\cos^2\\alpha}{\\sen^2\\alpha\\cos^2\\alpha}\\\\ =\\sec^2\\alpha\\cdot\\cosec^2\\alpha\\end{gathered}$ الفرق يساوي 0.', '$\\begin{gathered}\\sec^2\\alpha+\\cosec^2\\alpha\\\\ =\\frac{\\sen^2\\alpha+\\cos^2\\alpha}{\\sen^2\\alpha\\cos^2\\alpha}\\\\ =\\sec^2\\alpha\\cdot\\cosec^2\\alpha\\end{gathered}$ The difference is 0.'), answer: { expected: n(0) } },
            { id: 9, difficulty: 'hard', question: say('Sinplifikatu $(\\sen\\alpha+\\cos\\alpha)^2+(\\sen\\alpha-\\cos\\alpha)^2$.', 'Simplifica $(\\sen\\alpha+\\cos\\alpha)^2+(\\sen\\alpha-\\cos\\alpha)^2$.', 'بسّط $(\\sen\\alpha+\\cos\\alpha)^2+(\\sen\\alpha-\\cos\\alpha)^2$.', 'Simplify $(\\sin\\alpha+\\cos\\alpha)^2+(\\sin\\alpha-\\cos\\alpha)^2$.'), solution: same('$2\\sen^2\\alpha+2\\cos^2\\alpha=2$'), answer: { expected: n(2) } },
            { id: 10, difficulty: 'hard', question: say('$\\tg\\alpha=2$ bada, kalkulatu $\\frac{\\sen\\alpha+\\cos\\alpha}{\\sen\\alpha-\\cos\\alpha}$.', 'Si $\\tg\\alpha=2$, calcula $\\frac{\\sen\\alpha+\\cos\\alpha}{\\sen\\alpha-\\cos\\alpha}$.', 'إذا كان $\\tg\\alpha=2$، فاحسب $\\frac{\\sen\\alpha+\\cos\\alpha}{\\sen\\alpha-\\cos\\alpha}$.', 'If $\\tan\\alpha=2$, work out $\\frac{\\sin\\alpha+\\cos\\alpha}{\\sin\\alpha-\\cos\\alpha}$.'), solution: say('Zatitu goikoa eta behekoa $\\cos\\alpha$ adierazpenaz: $\\frac{\\tg\\alpha+1}{\\tg\\alpha-1}=\\frac{3}{1}=3$.', 'Divide arriba y abajo entre $\\cos\\alpha$: $\\frac{\\tg\\alpha+1}{\\tg\\alpha-1}=\\frac{3}{1}=3$.', 'اقسم البسط والمقام على $\\cos\\alpha$: $\\frac{\\tg\\alpha+1}{\\tg\\alpha-1}=\\frac{3}{1}=3$.', 'Divide the top and the bottom by $\\cos\\alpha$: $\\frac{\\tan\\alpha+1}{\\tan\\alpha-1}=\\frac{3}{1}=3$.'), answer: { expected: n(3) } }
        ]
    },
    {
        id: 'sums',
        title: say('Batuketa eta kenketa', 'Suma y resta', 'المجموع والفرق', 'Sums and differences'),
        items: [
            { id: 11, difficulty: 'easy', question: say('Idatzi $\\sen(\\alpha-\\beta)$ adierazpenaren formula.', 'Escribe la fórmula de $\\sen(\\alpha-\\beta)$.', 'اكتب صيغة $\\sen(\\alpha-\\beta)$.', 'Write the formula for $\\sin(\\alpha-\\beta)$.'), solution: same('$\\sen\\alpha\\cos\\beta-\\cos\\alpha\\sen\\beta$') },
            { id: 12, difficulty: 'easy', question: say('Kalkulatu $\\sen 15°$ kalkulagailurik gabe.', 'Calcula $\\sen 15°$ sin calculadora.', 'احسب $\\sen 15°$ دون آلة حاسبة.', 'Work out $\\sin 15°$ without a calculator.'), solution: same('$\\begin{gathered}\\sen(45°-30°)\\\\ =\\frac{\\sqrt{6}}{4}-\\frac{\\sqrt{2}}{4}=\\frac{\\sqrt{6}-\\sqrt{2}}{4}\\end{gathered}$') },
            { id: 13, difficulty: 'easy', question: with_(say('Kalkulatu $\\cos 15°$ kalkulagailurik gabe.', 'Calcula $\\cos 15°$ sin calculadora.', 'احسب $\\cos 15°$ دون آلة حاسبة.', 'Work out $\\cos 15°$ without a calculator.'), HUNDREDTHS), solution: same('$\\begin{gathered}\\cos(45°-30°)\\\\ =\\frac{\\sqrt{6}+\\sqrt{2}}{4}\\approx 0{,}97\\end{gathered}$'), answer: { expected: v('0,97') } },
            { id: 14, difficulty: 'medium', question: with_(say('α eta β zorrotzak dira, $\\sen\\alpha=\\frac{8}{17}$ eta $\\sen\\beta=\\frac{3}{5}$. Kalkulatu $\\sen(\\alpha+\\beta)$.', 'α y β son agudos, $\\sen\\alpha=\\frac{8}{17}$ y $\\sen\\beta=\\frac{3}{5}$. Halla $\\sen(\\alpha+\\beta)$.', 'α وβ حادتان، و$\\sen\\alpha=\\frac{8}{17}$ و$\\sen\\beta=\\frac{3}{5}$. أوجد $\\sen(\\alpha+\\beta)$.', 'α and β are acute, $\\sin\\alpha=\\frac{8}{17}$ and $\\sin\\beta=\\frac{3}{5}$. Find $\\sin(\\alpha+\\beta)$.'), AS_FRACTION), solution: same('$\\begin{gathered}\\cos\\alpha=\\frac{15}{17}\\qquad\\cos\\beta=\\frac{4}{5}\\\\ \\frac{32}{85}+\\frac{45}{85}=\\frac{77}{85}\\end{gathered}$'), answer: { expected: f(77, 85) } },
            { id: 15, difficulty: 'medium', question: with_(say('Kalkulatu $\\tg 105°$ kalkulagailurik gabe.', 'Calcula $\\tg 105°$ sin calculadora.', 'احسب $\\tg 105°$ دون آلة حاسبة.', 'Work out $\\tan 105°$ without a calculator.'), HUNDREDTHS), solution: same('$\\begin{gathered}\\tg(60°+45°)=\\frac{\\sqrt{3}+1}{1-\\sqrt{3}}\\\\ =-2-\\sqrt{3}\\approx -3{,}73\\end{gathered}$'), answer: { expected: v('-3,73') } },
            { id: 16, difficulty: 'medium', question: say('Sinplifikatu $\\sen(90°-\\alpha)$ kenketaren formularekin.', 'Simplifica $\\sen(90°-\\alpha)$ con la fórmula de la resta.', 'بسّط $\\sen(90°-\\alpha)$ بصيغة الفرق.', 'Simplify $\\sin(90°-\\alpha)$ with the difference formula.'), solution: same('$\\begin{gathered}\\sen 90°\\cos\\alpha-\\cos 90°\\sen\\alpha\\\\ =\\cos\\alpha\\end{gathered}$') },
            { id: 17, difficulty: 'medium', question: with_(say('Kalkulatu $\\sen 50°\\cos 10°+\\cos 50°\\sen 10°$ kalkulagailurik gabe.', 'Calcula $\\sen 50°\\cos 10°+\\cos 50°\\sen 10°$ sin calculadora.', 'احسب $\\sen 50°\\cos 10°+\\cos 50°\\sen 10°$ دون آلة حاسبة.', 'Work out $\\sin 50°\\cos 10°+\\cos 50°\\sin 10°$ without a calculator.'), HUNDREDTHS), solution: same('$\\sen(50°+10°)=\\frac{\\sqrt{3}}{2}\\approx 0{,}87$'), answer: { expected: v('0,87') } },
            { id: 18, difficulty: 'hard', question: with_(say('$\\tg(\\alpha+\\beta)=1$ eta $\\tg\\alpha=\\frac{1}{2}$ dira. Kalkulatu $\\tg\\beta$.', '$\\tg(\\alpha+\\beta)=1$ y $\\tg\\alpha=\\frac{1}{2}$. Halla $\\tg\\beta$.', '$\\tg(\\alpha+\\beta)=1$ و$\\tg\\alpha=\\frac{1}{2}$. أوجد $\\tg\\beta$.', '$\\tan(\\alpha+\\beta)=1$ and $\\tan\\alpha=\\frac{1}{2}$. Find $\\tan\\beta$.'), AS_FRACTION), solution: same('$\\frac{\\frac{1}{2}+t}{1-\\frac{t}{2}}=1\\ \\to\\ t=\\frac{1}{3}$'), answer: { expected: f(1, 3) } },
            { id: 19, difficulty: 'hard', question: say('Sinplifikatu $\\frac{\\cos(\\alpha+\\beta)+\\cos(\\alpha-\\beta)}{2\\cos\\alpha}$, eta kalkulatu haren balioa $\\beta=60°$ denean.', 'Simplifica $\\frac{\\cos(\\alpha+\\beta)+\\cos(\\alpha-\\beta)}{2\\cos\\alpha}$ y calcula su valor para $\\beta=60°$.', 'بسّط $\\frac{\\cos(\\alpha+\\beta)+\\cos(\\alpha-\\beta)}{2\\cos\\alpha}$ واحسب قيمتها عندما $\\beta=60°$.', 'Simplify $\\frac{\\cos(\\alpha+\\beta)+\\cos(\\alpha-\\beta)}{2\\cos\\alpha}$ and work out its value for $\\beta=60°$.'), solution: same('$\\begin{gathered}\\frac{2\\cos\\alpha\\cos\\beta}{2\\cos\\alpha}=\\cos\\beta\\\\ \\cos 60°=0{,}5\\end{gathered}$'), answer: { expected: v('0,5') } },
            { id: 20, difficulty: 'hard', question: say('Kalkulatu $\\frac{\\tg 70°-\\tg 25°}{1+\\tg 70°\\tg 25°}$ kalkulagailurik gabe.', 'Calcula $\\frac{\\tg 70°-\\tg 25°}{1+\\tg 70°\\tg 25°}$ sin calculadora.', 'احسب $\\frac{\\tg 70°-\\tg 25°}{1+\\tg 70°\\tg 25°}$ دون آلة حاسبة.', 'Work out $\\frac{\\tan 70°-\\tan 25°}{1+\\tan 70°\\tan 25°}$ without a calculator.'), solution: same('$\\tg(70°-25°)=\\tg 45°=1$'), answer: { expected: n(1) } }
        ]
    },
    {
        id: 'double',
        title: say('Bikoitza eta erdia', 'Doble y mitad', 'الضعف والنصف', 'Double and half'),
        items: [
            { id: 21, difficulty: 'easy', question: say('Idatzi $\\cos 2\\alpha$ α angeluaren sinuarekin bakarrik.', 'Escribe $\\cos 2\\alpha$ solo con el seno de α.', 'اكتب $\\cos 2\\alpha$ بجيب α فقط.', 'Write $\\cos 2\\alpha$ using only the sine of α.'), solution: same('$\\cos 2\\alpha=1-2\\sen^2\\alpha$') },
            { id: 22, difficulty: 'easy', question: say('$\\sen\\alpha=0{,}6$ eta $\\cos\\alpha=0{,}8$ dira. Kalkulatu $\\sen 2\\alpha$.', '$\\sen\\alpha=0{,}6$ y $\\cos\\alpha=0{,}8$. Halla $\\sen 2\\alpha$.', '$\\sen\\alpha=0{,}6$ و$\\cos\\alpha=0{,}8$. أوجد $\\sen 2\\alpha$.', '$\\sin\\alpha=0{,}6$ and $\\cos\\alpha=0{,}8$. Find $\\sin 2\\alpha$.'), solution: same('$2\\cdot 0{,}6\\cdot 0{,}8=0{,}96$'), answer: { expected: v('0,96') } },
            { id: 23, difficulty: 'easy', question: say('$\\cos\\alpha=0{,}5$ da. Kalkulatu $\\cos 2\\alpha$.', '$\\cos\\alpha=0{,}5$. Halla $\\cos 2\\alpha$.', '$\\cos\\alpha=0{,}5$. أوجد $\\cos 2\\alpha$.', '$\\cos\\alpha=0{,}5$. Find $\\cos 2\\alpha$.'), solution: same('$2\\cdot 0{,}25-1=-0{,}5$'), answer: { expected: v('-0,5') } },
            { id: 24, difficulty: 'medium', question: with_(say('$\\sen\\alpha=\\frac{5}{13}$ da, eta α bigarren koadrantean dago. Kalkulatu $\\sen 2\\alpha$.', '$\\sen\\alpha=\\frac{5}{13}$ y α está en el segundo cuadrante. Halla $\\sen 2\\alpha$.', '$\\sen\\alpha=\\frac{5}{13}$ وα في الربع الثاني. أوجد $\\sen 2\\alpha$.', '$\\sin\\alpha=\\frac{5}{13}$ and α is in the second quadrant. Find $\\sin 2\\alpha$.'), AS_FRACTION), solution: same('$2\\cdot\\frac{5}{13}\\cdot\\left(-\\frac{12}{13}\\right)=-\\frac{120}{169}$'), answer: { expected: f(-120, 169) } },
            { id: 25, difficulty: 'medium', question: with_(say('$\\cos\\alpha=-\\frac{1}{3}$ da, eta α bigarren koadrantean dago. Kalkulatu $\\cos\\frac{\\alpha}{2}$.', '$\\cos\\alpha=-\\frac{1}{3}$ y α está en el segundo cuadrante. Halla $\\cos\\frac{\\alpha}{2}$.', '$\\cos\\alpha=-\\frac{1}{3}$ وα في الربع الثاني. أوجد $\\cos\\frac{\\alpha}{2}$.', '$\\cos\\alpha=-\\frac{1}{3}$ and α is in the second quadrant. Find $\\cos\\frac{\\alpha}{2}$.'), HUNDREDTHS), solution: same('$\\sqrt{\\frac{1-\\frac{1}{3}}{2}}=\\sqrt{\\frac{1}{3}}\\approx 0{,}58$'), answer: { expected: v('0,58') } },
            { id: 26, difficulty: 'medium', question: with_(say('Kalkulatu $\\cos 22{,}5°$ angelu erdiaren formularekin.', 'Calcula $\\cos 22{,}5°$ con la fórmula del ángulo mitad.', 'احسب $\\cos 22{,}5°$ بصيغة نصف الزاوية.', 'Work out $\\cos 22{,}5°$ with the half-angle formula.'), THOUSANDTHS), solution: same('$\\sqrt{\\frac{1+\\cos 45°}{2}}\\approx 0{,}924$'), answer: { expected: v('0,924') } },
            { id: 27, difficulty: 'medium', question: say('Sinplifikatu $\\frac{\\sen 2\\alpha}{2\\sen\\alpha}$.', 'Simplifica $\\frac{\\sen 2\\alpha}{2\\sen\\alpha}$.', 'بسّط $\\frac{\\sen 2\\alpha}{2\\sen\\alpha}$.', 'Simplify $\\frac{\\sin 2\\alpha}{2\\sin\\alpha}$.'), solution: same('$\\frac{2\\sen\\alpha\\cos\\alpha}{2\\sen\\alpha}=\\cos\\alpha$') },
            { id: 28, difficulty: 'hard', question: say('Idatzi $\\cos 50°+\\cos 10°$ biderkadura gisa.', 'Transforma en producto $\\cos 50°+\\cos 10°$.', 'حوّل $\\cos 50°+\\cos 10°$ إلى جداء.', 'Write $\\cos 50°+\\cos 10°$ as a product.'), solution: same('$2\\cos 30°\\cos 20°=\\sqrt{3}\\cos 20°$') },
            { id: 29, difficulty: 'hard', question: with_(say('Sinplifikatu $\\frac{1-\\cos 2\\alpha}{\\sen 2\\alpha}$, eta kalkulatu haren balioa $\\alpha=30°$ denean.', 'Simplifica $\\frac{1-\\cos 2\\alpha}{\\sen 2\\alpha}$ y calcula su valor para $\\alpha=30°$.', 'بسّط $\\frac{1-\\cos 2\\alpha}{\\sen 2\\alpha}$ واحسب قيمتها عندما $\\alpha=30°$.', 'Simplify $\\frac{1-\\cos 2\\alpha}{\\sin 2\\alpha}$ and work out its value for $\\alpha=30°$.'), HUNDREDTHS), solution: same('$\\begin{gathered}\\frac{2\\sen^2\\alpha}{2\\sen\\alpha\\cos\\alpha}=\\tg\\alpha\\\\ \\tg 30°\\approx 0{,}58\\end{gathered}$'), answer: { expected: v('0,58') } },
            { id: 30, difficulty: 'hard', question: say('Egiaztatu $\\alpha=30°$ denean $\\sen 3\\alpha=3\\sen\\alpha-4\\sen^3\\alpha$ betetzen dela.', 'Comprueba con $\\alpha=30°$ que $\\sen 3\\alpha=3\\sen\\alpha-4\\sen^3\\alpha$.', 'تحقق عندما $\\alpha=30°$ من أن $\\sen 3\\alpha=3\\sen\\alpha-4\\sen^3\\alpha$.', 'Check with $\\alpha=30°$ that $\\sin 3\\alpha=3\\sin\\alpha-4\\sin^3\\alpha$.'), solution: same('$\\begin{gathered}\\sen 90°=1\\\\ 3\\cdot\\frac{1}{2}-4\\cdot\\frac{1}{8}=1\\end{gathered}$') }
        ]
    },
    {
        id: 'equations',
        title: say('Ekuazioak', 'Ecuaciones', 'المعادلات', 'Equations'),
        items: [
            { id: 31, difficulty: 'easy', question: say('Ebatzi $\\sen x=1$, 0°-tik 360°-ra.', 'Resuelve $\\sen x=1$ entre 0° y 360°.', 'حُلّ $\\sen x=1$ بين 0° و360°.', 'Solve $\\sin x=1$ between 0° and 360°.'), solution: same('$x=90°$'), answer: { expected: n(90) } },
            { id: 32, difficulty: 'easy', question: say('Ebatzi $2\\cos x=\\sqrt{3}$, 0°-tik 360°-ra. Eman soluzio handiena.', 'Resuelve $2\\cos x=\\sqrt{3}$ entre 0° y 360°. Da la solución mayor.', 'حُلّ $2\\cos x=\\sqrt{3}$ بين 0° و360°. أعطِ أكبر حل.', 'Solve $2\\cos x=\\sqrt{3}$ between 0° and 360°. Give the largest solution.'), solution: same('$x=30°\\qquad x=360°-30°=330°$'), answer: { expected: n(330) } },
            { id: 33, difficulty: 'easy', question: say('Idatzi $\\tg x=\\sqrt{3}$ ekuazioaren soluzio orokorra.', 'Escribe la solución general de $\\tg x=\\sqrt{3}$.', 'اكتب الحل العام للمعادلة $\\tg x=\\sqrt{3}$.', 'Write the general solution of $\\tan x=\\sqrt{3}$.'), solution: same('$x=60°+k\\cdot 180°$') },
            { id: 34, difficulty: 'medium', question: say('Ebatzi $\\sen x=-\\frac{\\sqrt{2}}{2}$, 0°-tik 360°-ra, eta batu soluzioak.', 'Resuelve $\\sen x=-\\frac{\\sqrt{2}}{2}$ entre 0° y 360° y suma las soluciones.', 'حُلّ $\\sen x=-\\frac{\\sqrt{2}}{2}$ بين 0° و360° واجمع الحلول.', 'Solve $\\sin x=-\\frac{\\sqrt{2}}{2}$ between 0° and 360° and add up the solutions.'), solution: same('$225°+315°=540°$'), answer: { expected: n(540) } },
            { id: 35, difficulty: 'medium', question: say('Zenbat soluzio ditu $4\\sen^2x=1$ ekuazioak, 0°-tik 360°-ra?', '¿Cuántas soluciones tiene $4\\sen^2x=1$ entre 0° y 360°?', 'كم حلًّا للمعادلة $4\\sen^2x=1$ بين 0° و360°؟', 'How many solutions does $4\\sin^2x=1$ have between 0° and 360°?'), solution: say('$\\sen x=\\pm\\frac{1}{2}$ ekuaziotik, 4 soluzio: $x=30°,\\ 150°,\\ 210°,\\ 330°$.', 'De $\\sen x=\\pm\\frac{1}{2}$ salen 4 soluciones: $x=30°,\\ 150°,\\ 210°,\\ 330°$.', 'من $\\sen x=\\pm\\frac{1}{2}$ نحصل على 4 حلول: $x=30°,\\ 150°,\\ 210°,\\ 330°$.', 'From $\\sin x=\\pm\\frac{1}{2}$ you get 4 solutions: $x=30°,\\ 150°,\\ 210°,\\ 330°$.'), answer: { expected: n(4) } },
            { id: 36, difficulty: 'medium', question: say('Ebatzi $2\\sen^2x=3\\cos x$, 0°-tik 360°-ra. Eman soluzio handiena.', 'Resuelve $2\\sen^2x=3\\cos x$ entre 0° y 360°. Da la solución mayor.', 'حُلّ $2\\sen^2x=3\\cos x$ بين 0° و360°. أعطِ أكبر حل.', 'Solve $2\\sin^2x=3\\cos x$ between 0° and 360°. Give the largest solution.'), solution: say('$2\\cos^2x+3\\cos x-2=0$ ekuaziotik, $\\cos x=\\frac{1}{2}$ (60° eta 300°); $\\cos x=-2$ baztertu egiten da.', 'De $2\\cos^2x+3\\cos x-2=0$ sale $\\cos x=\\frac{1}{2}$ (60° y 300°); $\\cos x=-2$ se descarta.', 'من $2\\cos^2x+3\\cos x-2=0$ نحصل على $\\cos x=\\frac{1}{2}$ (60° و300°)؛ و$\\cos x=-2$ تُستبعد.', 'From $2\\cos^2x+3\\cos x-2=0$ you get $\\cos x=\\frac{1}{2}$ (60° and 300°); $\\cos x=-2$ is discarded.'), answer: { expected: n(300) } },
            { id: 37, difficulty: 'medium', question: say('Ebatzi $\\cos 2x=\\frac{1}{2}$, 0°-tik 360°-ra, eta batu soluzioak.', 'Resuelve $\\cos 2x=\\frac{1}{2}$ entre 0° y 360° y suma las soluciones.', 'حُلّ $\\cos 2x=\\frac{1}{2}$ بين 0° و360° واجمع الحلول.', 'Solve $\\cos 2x=\\frac{1}{2}$ between 0° and 360° and add up the solutions.'), solution: same('$\\begin{gathered}2x=60°,\\ 300°,\\ 420°,\\ 660°\\\\ 30°+150°+210°+330°=720°\\end{gathered}$'), answer: { expected: n(720) } },
            { id: 38, difficulty: 'hard', question: say('Zenbat soluzio ditu $\\cos 2x+3\\sen x=2$ ekuazioak, 0°-tik 360°-ra?', '¿Cuántas soluciones tiene $\\cos 2x+3\\sen x=2$ entre 0° y 360°?', 'كم حلًّا للمعادلة $\\cos 2x+3\\sen x=2$ بين 0° و360°؟', 'How many solutions does $\\cos 2x+3\\sin x=2$ have between 0° and 360°?'), solution: say('$2\\sen^2x-3\\sen x+1=0$ ekuaziotik, $\\sen x=1$ (90°) eta $\\sen x=\\frac{1}{2}$ (30° eta 150°): 3 soluzio.', 'De $2\\sen^2x-3\\sen x+1=0$ sale $\\sen x=1$ (90°) y $\\sen x=\\frac{1}{2}$ (30° y 150°): 3 soluciones.', 'من $2\\sen^2x-3\\sen x+1=0$ نحصل على $\\sen x=1$ (90°) و$\\sen x=\\frac{1}{2}$ (30° و150°): 3 حلول.', 'From $2\\sin^2x-3\\sin x+1=0$ you get $\\sin x=1$ (90°) and $\\sin x=\\frac{1}{2}$ (30° and 150°): 3 solutions.'), answer: { expected: n(3) } },
            { id: 39, difficulty: 'hard', question: say('Zenbat soluzio ditu $\\cos 3x=0$ ekuazioak, 0°-tik 360°-ra?', '¿Cuántas soluciones tiene $\\cos 3x=0$ entre 0° y 360°?', 'كم حلًّا للمعادلة $\\cos 3x=0$ بين 0° و360°؟', 'How many solutions does $\\cos 3x=0$ have between 0° and 360°?'), solution: say('$3x$ angeluak hiru bira ematen ditu: 6 soluzio, $x=30°,\\ 90°,\\ 150°,\\ 210°,\\ 270°,\\ 330°$.', 'El ángulo $3x$ da tres vueltas: 6 soluciones, $x=30°,\\ 90°,\\ 150°,\\ 210°,\\ 270°,\\ 330°$.', 'تدور الزاوية $3x$ ثلاث دورات: 6 حلول، $x=30°,\\ 90°,\\ 150°,\\ 210°,\\ 270°,\\ 330°$.', 'The angle $3x$ makes three turns: 6 solutions, $x=30°,\\ 90°,\\ 150°,\\ 210°,\\ 270°,\\ 330°$.'), answer: { expected: n(6) } },
            { id: 40, difficulty: 'hard', question: say('Ebatzi $\\tg^2x=\\sec x+1$, 0°-tik 360°-ra. Eman soluzio txikiena.', 'Resuelve $\\tg^2x=\\sec x+1$ entre 0° y 360°. Da la solución menor.', 'حُلّ $\\tg^2x=\\sec x+1$ بين 0° و360°. أعطِ أصغر حل.', 'Solve $\\tan^2x=\\sec x+1$ between 0° and 360°. Give the smallest solution.'), solution: same('$\\begin{gathered}\\sec^2x-\\sec x-2=0\\\\ \\sec x=2\\ \\to\\ 60°,\\ 300°\\qquad\\sec x=-1\\ \\to\\ 180°\\end{gathered}$'), answer: { expected: n(60) } }
        ]
    },
    {
        id: 'functions',
        title: say('Funtzioak', 'Funciones', 'الدوال', 'Functions'),
        items: [
            { id: 41, difficulty: 'easy', question: say('Zein da $y=\\tg x$ funtzioaren periodoa?', '¿Cuál es el periodo de $y=\\tg x$?', 'ما دور الدالة $y=\\tg x$؟', 'What is the period of $y=\\tan x$?'), solution: same('$T=\\pi$') },
            { id: 42, difficulty: 'easy', question: say('Zein da $y=2\\sen x+1$ funtzioaren balio handiena?', '¿Cuál es el valor máximo de $y=2\\sen x+1$?', 'ما القيمة العظمى للدالة $y=2\\sen x+1$؟', 'What is the maximum value of $y=2\\sin x+1$?'), solution: same('$2\\cdot 1+1=3$'), answer: { expected: n(3) } },
            { id: 43, difficulty: 'easy', question: say('Zenbat da $\\cos x$, $x=\\pi$ denean?', '¿Cuánto vale $\\cos x$ en $x=\\pi$?', 'كم قيمة $\\cos x$ عندما $x=\\pi$؟', 'What is $\\cos x$ at $x=\\pi$?'), solution: same('$\\cos\\pi=-1$'), answer: { expected: n(-1) } },
            { id: 44, difficulty: 'medium', question: say('$y=\\sen 4x$ funtzioaren periodoa $a\\pi$ da. Kalkulatu $a$.', 'El periodo de $y=\\sen 4x$ es $a\\pi$. Halla $a$.', 'دور الدالة $y=\\sen 4x$ هو $a\\pi$. أوجد $a$.', 'The period of $y=\\sin 4x$ is $a\\pi$. Find $a$.'), solution: same('$T=\\frac{2\\pi}{4}=\\frac{\\pi}{2}\\ \\to\\ a=\\frac{1}{2}$'), answer: { expected: v('0,5') } },
            { id: 45, difficulty: 'medium', question: say('Zein da $y=3\\cos x-1$ funtzioaren balio txikiena?', '¿Cuál es el valor mínimo de $y=3\\cos x-1$?', 'ما القيمة الصغرى للدالة $y=3\\cos x-1$؟', 'What is the minimum value of $y=3\\cos x-1$?'), solution: same('$3\\cdot(-1)-1=-4$'), answer: { expected: n(-4) } },
            { id: 46, difficulty: 'medium', question: say('$y=\\cos\\left(2x+\\frac{\\pi}{2}\\right)$ funtzioaren desfasea $a\\pi$ da. Kalkulatu $a$.', 'El desfase de $y=\\cos\\left(2x+\\frac{\\pi}{2}\\right)$ es $a\\pi$. Halla $a$.', 'انزياح طور الدالة $y=\\cos\\left(2x+\\frac{\\pi}{2}\\right)$ هو $a\\pi$. أوجد $a$.', 'The phase shift of $y=\\cos\\left(2x+\\frac{\\pi}{2}\\right)$ is $a\\pi$. Find $a$.'), solution: same('$\\begin{gathered}2x+\\frac{\\pi}{2}=0\\ \\to\\ x=-\\frac{\\pi}{4}\\\\ a=-\\frac{1}{4}\\end{gathered}$'), answer: { expected: v('-0,25') } },
            { id: 47, difficulty: 'medium', question: say('Zenbat aldiz ebakitzen du $y=\\cos x$ grafikoak $y=0{,}3$ zuzena, 0 eta $4\\pi$ artean?', '¿Cuántas veces corta $y=\\cos x$ a la recta $y=0{,}3$ entre 0 y $4\\pi$?', 'كم مرة يقطع $y=\\cos x$ المستقيم $y=0{,}3$ بين 0 و$4\\pi$؟', 'How many times does $y=\\cos x$ cross the line $y=0{,}3$ between 0 and $4\\pi$?'), solution: say('Bi ebakidura periodo bakoitzean, eta bi periodo daude: 4.', 'Dos cortes en cada periodo, y hay dos periodos: 4.', 'تقاطعان في كل دور، وهناك دوران: 4.', 'Two crossings in each period, and there are two periods: 4.'), answer: { expected: n(4) } },
            { id: 48, difficulty: 'hard', question: say('Uhin bat 2 eta 8 artean ibiltzen da eta 12 orduan behin errepikatzen da. Idatzi $y=D+A\\cos(B\\cdot t)$ gisa, eta eman B gradutan orduko.', 'Una onda va de 2 a 8 y se repite cada 12 horas. Escríbela como $y=D+A\\cos(B\\cdot t)$ y da B en grados por hora.', 'موجة تتراوح بين 2 و8 وتتكرر كل 12 ساعة. اكتبها على شكل $y=D+A\\cos(B\\cdot t)$ وأعطِ B بالدرجات في الساعة.', 'A wave goes from 2 to 8 and repeats every 12 hours. Write it as $y=D+A\\cos(B\\cdot t)$ and give B in degrees per hour.'), solution: same('$\\begin{gathered}D=5\\qquad A=3\\\\ B=\\frac{360°}{12}=30°\\end{gathered}$'), answer: { expected: n(30) } },
            { id: 49, difficulty: 'hard', question: say('Noria bateko kabinaren altuera $h(t)=20-18\\cos(6°\\cdot t)$ da, metrotan eta segundotan. Zenbat segundo behar ditu bira bat emateko?', 'La altura de una cabina de noria es $h(t)=20-18\\cos(6°\\cdot t)$, en metros y segundos. ¿Cuántos segundos tarda en dar una vuelta?', 'ارتفاع عربة دولاب $h(t)=20-18\\cos(6°\\cdot t)$ بالأمتار والثواني. كم ثانية يستغرق لإكمال دورة؟', 'The height of a Ferris wheel cabin is $h(t)=20-18\\cos(6°\\cdot t)$, in metres and seconds. How many seconds does one turn take?'), solution: same('$\\frac{360°}{6°}=60$'), answer: { expected: n(60) } },
            { id: 50, difficulty: 'hard', question: say('Kabinaren altuera $h(t)=20-18\\cos(6°\\cdot t)$ bada, zer altueratan dago 10 s-ren buruan?', 'Si la altura de la cabina es $h(t)=20-18\\cos(6°\\cdot t)$, ¿a qué altura está a los 10 s?', 'إذا كان ارتفاع العربة $h(t)=20-18\\cos(6°\\cdot t)$، فما ارتفاعها بعد 10 ث؟', 'If the height of the cabin is $h(t)=20-18\\cos(6°\\cdot t)$, how high is it after 10 s?'), solution: same('$h(10)=20-18\\cdot\\cos 60°=11$'), answer: { expected: n(11) } }
        ]
    }
]
